import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { SvgFrame, springIn } from "../motion";

export const fps = 30;
export const durationInFrames = 90;

const NEW_ROW_BOTTOM_PCT = 12;

export default function NewRowReveal() {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const t = springIn(frame, vfps, 18, "ELASTIC");
  const bottom = NEW_ROW_BOTTOM_PCT * (1 - t);
  return (
    <AbsoluteFill style={{ background: "#161718" }}>
      <SvgFrame index={1} style={{ clipPath: `inset(0 0 ${bottom}% 0)` }} />
    </AbsoluteFill>
  );
}
